# Optional semantic assertions. Legacy deliverables without assertions retain
# their historical mechanical-completeness contract.
def normalize_semantic_requirements(value: Any) -> list[dict[str, Any]]:
    if value is None:
        return []
    if not isinstance(value, list) or not value or len(value) > 64:
        raise ValueError("SEMANTIC_REQUIREMENTS_INVALID")
    normalized: list[dict[str, Any]] = []
    for rule in value:
        if not isinstance(rule, dict) or set(rule) - {"selector", "operator", "expected"}:
            raise ValueError("SEMANTIC_REQUIREMENT_INVALID")
        selector = _normalize_json_path_selector(rule.get("selector"))
        operator = rule.get("operator")
        if operator not in ("present", "non_empty", "equals", "min_items"):
            raise ValueError("SEMANTIC_OPERATOR_UNSUPPORTED")
        if operator == "equals":
            if "expected" not in rule or not isinstance(rule["expected"], (str, int, float, bool, type(None))):
                raise ValueError("SEMANTIC_EXPECTED_INVALID")
        elif operator == "min_items":
            if type(rule.get("expected")) is not int or not 1 <= rule["expected"] <= 10000:
                raise ValueError("SEMANTIC_EXPECTED_INVALID")
        elif "expected" in rule:
            raise ValueError("SEMANTIC_EXPECTED_UNEXPECTED")
        normalized.append({
            "selector": selector,
            "operator": operator,
            **({"expected": rule["expected"]} if "expected" in rule else {}),
        })
    return normalized


def evaluate_semantic_deliverables(
    required_deliverables: Any,
    deliverable_specs: Any,
    deliverables: Any,
) -> list[str]:
    """Fail closed for declared semantic assertions, without changing legacy jobs."""
    specs = normalize_deliverable_specs(deliverable_specs, required_deliverables)
    materialized = normalize_materialized_deliverables(deliverables)
    failures: list[str] = []
    for name, spec in specs.items():
        for index, rule in enumerate(spec.get("semantic_requirements", []), 1):
            reason = None
            try:
                value = resolve_json_path(
                    materialized.get(name),
                    rule["selector"]["path"],
                )
            except ValueError:
                value = None
                reason = "PATH_MISSING"
            op = rule["operator"]
            if reason is None:
                if op == "present":
                    valid = value is not None
                elif op == "non_empty":
                    valid = deliverable_payload_present(value)
                elif op == "equals":
                    valid = type(value) is type(rule["expected"]) and value == rule["expected"]
                elif op == "min_items":
                    valid = isinstance(value, (list, dict)) and len(value) >= rule["expected"]
                else:
                    valid = False
                if not valid:
                    reason = "ASSERTION_FAILED"
            if reason:
                failures.append(f"{name}:{index}:{reason}")
    return failures

