def test_r4_semantic_validation_positive_and_negative():
    from tools.mirror_sync.worker_deliverable_contract import (
        evaluate_semantic_deliverables,
    )
    specs = {"EXAMPLE_OUTPUT": {
        "source": {"check_type": "repository_contract_audit", "occurrence": 1},
        "selector": {"type": "json_path", "path": ["payload"]},
        "semantic_requirements": [
            {"selector": {"type": "json_path", "path": ["semantic_valid"]},
             "operator": "equals", "expected": True},
            {"selector": {"type": "json_path", "path": ["evidence_refs"]},
             "operator": "min_items", "expected": 1},
        ],
    }}
    assert not evaluate_semantic_deliverables(
        ["EXAMPLE_OUTPUT"], specs,
        {"EXAMPLE_OUTPUT": {"semantic_valid": True, "evidence_refs": ["repo:path"]}},
    )
    assert evaluate_semantic_deliverables(
        ["EXAMPLE_OUTPUT"], specs,
        {"EXAMPLE_OUTPUT": {"semantic_valid": False, "evidence_refs": []}},
    )


def test_r4_unknown_operator_fails_closed():
    from tools.mirror_sync.worker_deliverable_contract import normalize_deliverable_specs
    try:
        normalize_deliverable_specs({
            "EXAMPLE_OUTPUT": {
                "source": {"check_type": "git_diff_check", "occurrence": 1},
                "selector": {"type": "json_path", "path": ["output"]},
                "semantic_requirements": [
                    {"selector": {"type": "json_path", "path": ["output"]},
                     "operator": "always_pass"},
                ],
            }
        }, ["EXAMPLE_OUTPUT"])
    except ValueError as exc:
        assert str(exc) == "SEMANTIC_OPERATOR_UNSUPPORTED"
    else:
        raise AssertionError("Unknown operator must fail closed")


def test_r4_publisher_refuses_semantically_invalid_mechanical_completion():
    publisher = load_module(
        "deliverable_publisher_semantic_r4",
        "tools/mirror_sync/universal_job_result_publisher.py",
    )
    result = generic_result()
    result["required_deliverables"] = ["EXAMPLE_OUTPUT"]
    result["deliverables"] = {"EXAMPLE_OUTPUT": {"semantic_valid": False}}
    result["deliverable_specs"] = {"EXAMPLE_OUTPUT": {
        "source": {"check_type": "git_diff_check", "occurrence": 1},
        "selector": {"type": "json_path", "path": ["output"]},
        "semantic_requirements": [{
            "selector": {"type": "json_path", "path": ["semantic_valid"]},
            "operator": "equals", "expected": True,
        }],
    }}
    evidence = publisher.certification_evidence(result)
    assert evidence["certified"] is False
    assert evidence["certification"] == "PENDING_SEMANTIC_DELIVERABLES"
    assert evidence["percent_complete"] <= 95
